{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const fail = (msg) => { process.stderr.write(msg + '\n'); process.exit(2) }
const lt = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

const args = process.argv.slice(2)
let mode = args[0], workers = 0
if (!((mode === 'waves' || mode === 'explain') && args.length === 1) && !(mode === 'pack' && args.length === 2)) {
  fail('error: usage: cli.js waves|explain|pack <workers>')
}
if (mode === 'pack') {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
}

let text = ''
try { text = readFileSync(0, 'utf8') } catch { text = '' }
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depLines = []
for (let i = 0; i < lines.length; i++) {
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const w = line.split(/\s+/)
  const n = i + 1
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depLines.push(w.slice(1))
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}
for (const names of depLines) for (const x of names) if (!cost.has(x)) fail(`error: unknown task ${x}`)
for (const k of cost.keys()) deps.set(k, new Set())
for (const [a, ...rest] of depLines) for (const d of rest) deps.get(a).add(d)
const names = [...cost.keys()].sort(lt)
const dl = new Map(names.map((k) => [k, [...deps.get(k)].sort(lt)]))

// cycle detection
const state = new Map()
const stack = []
function dfs(u) {
  state.set(u, 1)
  stack.push(u)
  for (const v of dl.get(u)) {
    if (state.get(v) === 1) {
      const c = stack.slice(stack.indexOf(v)).concat(v)
      process.stderr.write('error: cycle: ' + c.join(' -> ') + '\n')
      process.exit(3)
    }
    if (!state.has(v)) dfs(v)
  }
  stack.pop()
  state.set(u, 2)
}
for (const k of names) if (!state.has(k)) dfs(k)

// topological order (dependencies first)
const order = []
const seen = new Set()
function visit(u) {
  if (seen.has(u)) return
  seen.add(u)
  for (const v of dl.get(u)) visit(v)
  order.push(u)
}
for (const k of names) visit(k)

const start = new Map(), finish = new Map(), depth = new Map()
for (const u of order) {
  let s = 0, d = 0
  for (const v of dl.get(u)) { s = Math.max(s, finish.get(v)); d = Math.max(d, depth.get(v) + 1) }
  start.set(u, s); finish.set(u, s + cost.get(u)); depth.set(u, d)
}
const total = names.reduce((m, k) => Math.max(m, finish.get(k)), 0)
const out = []
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ||= []).push(k)
  ws.forEach((w, i) => out.push(`wave ${i}: ${w.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const k of names) out.push(`${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}`)
  out.push(`total ${total}`)
} else {
  const prio = new Map()
  for (const u of [...order].reverse()) {
    if (!prio.has(u)) prio.set(u, cost.get(u))
    for (const v of dl.get(u)) prio.set(v, Math.max(prio.get(v) ?? 0, 0))
  }
  const dependents = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const v of dl.get(k)) dependents.get(v).push(k)
  for (const u of [...order].reverse()) {
    let best = 0
    for (const p of dependents.get(u)) best = Math.max(best, prio.get(p))
    prio.set(u, cost.get(u) + best)
  }
  const free = new Array(workers).fill(0)
  const ran = Array.from({ length: workers }, () => [])
  const done = new Map() // started tasks -> finish
  let t = 0, mk = 0
  while (done.size < names.length) {
    for (;;) {
      const w = free.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const k of names) {
        if (done.has(k)) continue
        if (!dl.get(k).every((d) => done.has(d) && done.get(d) <= t)) continue
        if (pick === null || prio.get(k) > prio.get(pick)) pick = k
      }
      if (pick === null) break
      const f = t + cost.get(pick)
      done.set(pick, f)
      free[w] = f
      ran[w].push(`${pick}@${t}-${f}`)
      mk = Math.max(mk, f)
    }
    if (done.size >= names.length) break
    const nexts = [...free, ...done.values()].filter((x) => x > t)
    t = Math.min(...nexts)
  }
  ran.forEach((r, i) => out.push(`worker ${i}:` + r.map((x) => ' ' + x).join('')))
  out.push(`makespan ${mk}`)
}
process.stdout.write(out.join('\n') + (out.length ? '\n' : ''))
EOF
