{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'replay' && mode[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function count(field, text, least) {
  if (!UINT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

function run(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const results = []
  let started = false
  let lastTick = null

  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    try {
      handle(line.split(/\s+/))
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })

  function declCheck() {
    if (started) throw new Fail('declarations must come before the first event')
  }

  function handle(w) {
    switch (w[0]) {
      case 'bucket': {
        if (w.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        declCheck()
        if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        const capacity = count('capacity', w[2], 1)
        const refill = count('refill', w[3], 0)
        const per = count('per', w[4], 1)
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], { name: w[1], kind: 'bucket', capacity, refill, per, states: new Map() })
        break
      }
      case 'window': {
        if (w.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        declCheck()
        if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        const limit = count('limit', w[2], 0)
        const span = count('span', w[3], 1)
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], { name: w[1], kind: 'window', limit, span, states: new Map() })
        break
      }
      case 'route': {
        if (w.length < 3) throw new Fail('expected route <prefix> <policy>...')
        declCheck()
        if (!NAME.test(w[1])) throw new Fail(`invalid route prefix ${w[1]}`)
        if (routes.has(w[1])) throw new Fail(`prefix ${w[1]} is routed twice`)
        const list = []
        for (const n of w.slice(2)) {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          list.push(policies.get(n))
        }
        routes.set(w[1], list)
        break
      }
      case 'event': {
        if (w.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = count('tick', w[1], 0)
        if (!NAME.test(w[2])) throw new Fail(`invalid key ${w[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        started = true
        lastTick = tick
        results.push({ tick: w[1], key: w[2], deny: event(tick, w[2]) })
        break
      }
      default:
        throw new Fail(`unknown directive ${w[0]}`)
    }
  }

  function event(tick, key) {
    let best = null
    for (const [p, list] of routes) {
      if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
    }
    if (best === null) return null
    const list = routes.get(best)
    const sts = list.map((p) => {
      let s = p.states.get(key)
      if (!s) {
        s = p.kind === 'bucket' ? { tokens: p.capacity * p.per, last: tick } : { ticks: [] }
        p.states.set(key, s)
      }
      if (p.kind === 'bucket') {
        s.tokens += p.refill * (tick - s.last)
        const max = p.capacity * p.per
        if (s.tokens > max) s.tokens = max
        s.last = tick
      } else {
        const cut = tick - p.span
        s.ticks = s.ticks.filter((t) => t > cut)
      }
      return s
    })
    for (let i = 0; i < list.length; i++) {
      const p = list[i]
      const ok = p.kind === 'bucket' ? sts[i].tokens >= p.per : BigInt(sts[i].ticks.length) < p.limit
      if (!ok) return p.name
    }
    list.forEach((p, i) => {
      if (p.kind === 'bucket') sts[i].tokens -= p.per
      else sts[i].ticks.push(tick)
    })
    return null
  }

  return results
}

let results
try {
  results = run(readFileSync(0, 'utf8'))
} catch (e) {
  if (e instanceof Fail) {
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}

let out = ''
if (mode[0] === 'replay') {
  for (const r of results) out += `${r.tick} ${r.key} ${r.deny === null ? 'allow' : `deny ${r.deny}`}\n`
} else {
  const per = new Map()
  let a = 0
  let d = 0
  for (const r of results) {
    const c = per.get(r.key) ?? { a: 0, d: 0 }
    if (r.deny === null) { c.a++; a++ } else { c.d++; d++ }
    per.set(r.key, c)
  }
  for (const k of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    out += `${k} allowed=${per.get(k).a} denied=${per.get(k).d}\n`
  }
  out += `total allowed=${a} denied=${d}\n`
}
process.stdout.write(out)
EOF
