import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(msg, code = 2) { super(msg); this.code = code }
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const tasks = new Map()
  const deps = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (tasks.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      tasks.set(w[1], { name: w[1], cost: BigInt(w[2]), deps: new Set() })
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      deps.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const d of deps) for (const name of d) if (!tasks.has(name)) throw new Fail(`error: unknown task ${name}`)
  for (const d of deps) for (const x of d.slice(1)) tasks.get(d[0]).deps.add(x)
  return tasks
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function analyze(tasks) {
  const names = [...tasks.keys()].sort(cmp)
  const state = new Map()
  const stack = []
  const order = []
  const visit = (name) => {
    state.set(name, 1)
    stack.push(name)
    for (const d of [...tasks.get(name).deps].sort(cmp)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d)).concat(d)
        throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(name, 2)
    order.push(name)
  }
  for (const n of names) if (!state.get(n)) visit(n)
  let total = 0n
  for (const name of order) {
    const t = tasks.get(name)
    t.depth = 0
    t.start = 0n
    for (const d of t.deps) {
      const o = tasks.get(d)
      t.depth = Math.max(t.depth, o.depth + 1)
      if (o.finish > t.start) t.start = o.finish
    }
    t.finish = t.start + t.cost
    if (t.finish > total) total = t.finish
  }
  const users = new Map(names.map((n) => [n, []]))
  for (const t of tasks.values()) for (const d of t.deps) users.get(d).push(t.name)
  for (let i = order.length - 1; i >= 0; i--) {
    const t = tasks.get(order[i])
    let best = 0n
    for (const u of users.get(t.name)) if (tasks.get(u).prio > best) best = tasks.get(u).prio
    t.prio = t.cost + best
  }
  return { names, total }
}

function pack(tasks, names, workers) {
  const runs = Array.from({ length: workers }, () => [])
  const freeAt = new Array(workers).fill(0n)
  const done = new Map()
  let left = names.length
  let t = 0n
  let makespan = 0n
  while (left > 0) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let best = null
      for (const n of names) {
        if (done.has(n)) continue
        const k = tasks.get(n)
        let ok = true
        for (const d of k.deps) if (!done.has(d) || done.get(d) > t) { ok = false; break }
        if (ok && (best === null || k.prio > best.prio)) best = k
      }
      if (!best) break
      const fin = t + best.cost
      done.set(best.name, fin)
      freeAt[w] = fin
      runs[w].push(`${best.name}@${t}-${fin}`)
      if (fin > makespan) makespan = fin
      left--
    }
    if (left === 0) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  const out = runs.map((r, i) => `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`)
  out.push(`makespan ${makespan}\n`)
  return out.join('')
}

function main() {
  const args = process.argv.slice(2)
  const usage = 'error: usage: cli.js waves|explain|pack <workers>'
  const mode = args[0]
  let workers = 0
  if ((mode === 'waves' || mode === 'explain') && args.length === 1) {
    // ok
  } else if (mode === 'pack' && args.length === 2) {
    if (!/^[1-9][0-9]*$/.test(args[1])) throw new Fail('error: workers must be a positive integer')
    workers = Number(args[1])
  } else throw new Fail(usage)
  const tasks = parse(readFileSync(0, 'utf8'))
  const { names, total } = analyze(tasks)
  let out = ''
  if (mode === 'waves') {
    const waves = []
    for (const n of names) (waves[tasks.get(n).depth] ||= []).push(n)
    waves.forEach((w, i) => { out += `wave ${i}: ${w.join(' ')}\n` })
    out += `total ${total}\n`
  } else if (mode === 'explain') {
    for (const n of names) {
      const k = tasks.get(n)
      out += `${n} start=${k.start} finish=${k.finish} depth=${k.depth}\n`
    }
    out += `total ${total}\n`
  } else out = pack(tasks, names, workers)
  process.stdout.write(out)
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
