import { readFileSync } from 'node:fs'

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

class Fail extends Error {}

function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

function splitAuthority(a) {
  let userinfo, rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); rest = a.slice(at + 1) }
  const rb = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', rb + 1)
  let host = rest, port
  if (colon >= 0) { host = rest.slice(0, colon); port = rest.slice(colon + 1) }
  return { userinfo, host, port }
}

function checkPct(label, v) {
  if (v !== undefined && /%(?![0-9A-Fa-f]{2})/.test(v)) {
    throw new Fail(`the ${label} has a truncated percent-encoding`)
  }
}

function pct(v) {
  return v.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function removeDots(input) {
  let out = ''
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out = out.slice(0, out.lastIndexOf('/') < 0 ? 0 : out.lastIndexOf('/'))
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out += seg
      input = input.slice(seg.length)
    }
  }
  return out
}

function check(p) {
  checkPct('path', p.path)
  let sa
  if (p.authority !== undefined) {
    sa = splitAuthority(p.authority)
    checkPct('userinfo', sa.userinfo)
    checkPct('host', sa.host)
  }
  checkPct('query', p.query)
  checkPct('fragment', p.fragment)
  return sa
}

function normalize(p) {
  const sa = check(p)
  const scheme = p.scheme === undefined ? undefined : lower(p.scheme)
  let auth
  if (sa) {
    auth = ''
    if (sa.userinfo !== undefined) auth += pct(sa.userinfo) + '@'
    auth += lower(pct(sa.host))
    if (sa.port !== undefined) {
      const port = pct(sa.port)
      if (port !== '' && port !== DEFAULT_PORTS[scheme]) auth += ':' + port
    }
  }
  let path = removeDots(pct(p.path))
  if (auth !== undefined && path === '') path = '/'
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (auth !== undefined) out += '//' + auth
  out += path
  if (p.query !== undefined) out += '?' + pct(p.query)
  if (p.fragment !== undefined) out += '#' + pct(p.fragment)
  return out
}

function resolve(base, ref) {
  if (base.scheme === undefined) throw new Fail('the base has no scheme')
  const t = { fragment: ref.fragment }
  if (ref.scheme !== undefined) {
    Object.assign(t, { scheme: ref.scheme, authority: ref.authority, path: removeDots(ref.path), query: ref.query })
  } else if (ref.authority !== undefined) {
    Object.assign(t, { scheme: base.scheme, authority: ref.authority, path: removeDots(ref.path), query: ref.query })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
      t.query = ref.query
    }
  }
  return t
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  try {
    lines.forEach((line, idx) => {
      try {
        if (mode === 'normalize') out.push(normalize(parse(line)))
        else {
          const sp = line.indexOf(' ')
          if (sp < 0) throw new Fail('expected a base and a reference')
          const base = parse(line.slice(0, sp))
          const ref = parse(line.slice(sp + 1))
          out.push(normalize(resolve(base, ref)))
        }
      } catch (e) {
        if (e instanceof Fail) throw new Fail(`line ${idx + 1}: ${e.message}`)
        throw e
      }
    })
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  if (out.length) process.stdout.write(out.join('\n') + '\n')
}

main()
