  const q = L.s[L.i++]
  let out = ''
  if (q === "'") {
    const j = L.s.indexOf("'", L.i)
    if (j < 0) fail('unterminated string')
    out = L.s.slice(L.i, j)
    L.i = j + 1
    return out
