import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) fail('error: usage: cli.js rounds|tally')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let candidates = null
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (candidates !== null || ballots.length) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    candidates = t.slice(1)
  } else if (t[0] === 'ballot') {
    if (candidates === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!candidates.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
})
if (candidates === null) fail('error: no candidates')

const continuing = new Set(candidates)
const history = []
const out = []
let roundNo = 0
let result
for (;;) {
  roundNo++
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  history.push(counts)
  const list = [...counts.entries()].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  let line = `round ${roundNo}: ` + list.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) { result = 'no winner'; break }
  const win = list.find(([, v]) => v * 2n > active)
  if (win) { result = `winner ${win[0]}`; break }
  let min = list[list.length - 1][1]
  let tied = list.filter(([, v]) => v === min).map(([c]) => c)
  while (tied.length > 1) {
    let narrowed = false
    for (const h of history) {
      const vals = tied.map((c) => h.get(c))
      const m = vals.reduce((a, b) => (a < b ? a : b))
      if (vals.some((v) => v !== m)) {
        tied = tied.filter((c) => h.get(c) === m)
        narrowed = true
        break
      }
    }
    if (!narrowed) break
  }
  tied.sort()
  const elim = tied[tied.length - 1]
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
out.push(result)
if (mode === 'tally') process.stdout.write(`rounds ${roundNo}\n${result}\n`)
else process.stdout.write(out.join('\n') + '\n')
