const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  // line/col at each index, computed lazily in one pass
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1
  let c = 1
  for (let k = 0; k < n; k++) {
    lines[k] = l
    cols[k] = c
    if (cs[k] === '\n') { l++; c = 1 }
    else if (cs[k] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  lines[n] = l
  cols[n] = c
  const fail = (k, reason) => { throw new ScanError(lines[k], cols[k], reason) }
  const toks = []
  let i = 0

  // consume digits of a run (with single underscores between digits); returns new index
  const run = (j, ok) => {
    if (!ok(cs[j])) return j
    j++
    for (;;) {
      if (ok(cs[j])) j++
      else if (cs[j] === '_' && ok(cs[j + 1])) j += 2
      else break
    }
    return j
  }

  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (depth > 0) {
        if (i >= n) fail(start, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; i += 2 }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
