    }
    const start = i
    const push = (kind, value) => toks.push({ kind, value, line: lines[start], col: cols[start] })
    if (ch === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) fail(start, 'unterminated string')
      push('rawstring', cs.slice(i + 2, j).join(''))
      i = j + 1
      continue
    }
    if (isIdStart(ch)) {
      let j = i + 1
      while (isIdPart(cs[j])) j++
      const w = cs.slice(i, j).join('')
      push(KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i
      let bad = false
      const p = cs[i + 1]
      const pre = ch === '0' && p !== undefined ? p.toLowerCase() : ''
      if (pre === 'x' || pre === 'b' || pre === 'o') {
        const ok = pre === 'x' ? isHex : pre === 'b' ? isBin : isOct
        j = run(i + 2, ok)
        if (j === i + 2) bad = true
      } else {
        j = run(i, isDigit)
