      i = j
      continue
    }
    const two = ch + (cs[i + 1] || '')
    if (PUNCT2.has(two)) { push('punct', two); i += 2; continue }
    if (PUNCT1.has(ch)) { push('punct', ch); i++; continue }
    fail(i, `unexpected character ${ch}`)
  }
  return toks
}

