    const a = parseAddress(word)
    if (a) refs.push(a)
    return a
  }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      const r = add()
      l = { type: 'bin', op, l, r }
    }
    return l
  }
  function add() {
    let l = mul()
    while (peekOp('+') || peekOp('-')) {
