    let l = pow()
    while (peekOp('*') || peekOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (peekOp('^')) {
