export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9A-Fa-f]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const advN = (k) => { for (let j = 0; j < k; j++) adv() }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const sl = line, sc = col
      advN(2)
      let depth = 1
      while (depth > 0) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { advN(2); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { advN(2); depth-- }
        else adv()
      }
      continue
    }
    const sl = line, sc = col
    const push = (kind, body) => tokens.push({ line: sl, col: sc, kind, body })

    if (c === 'r' && cs[i + 1] === '"') {
      advN(2)
      let s = ''
      while (true) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = adv()
        if (d === '"') break
        s += d
      }
      push('rawstring', s)
      continue
    }
    if (isIdStart(c)) {
      let s = ''
      while (i < n && isIdPart(cs[i])) s += adv()
      push(KEYWORDS.has(s) ? 'keyword' : 'ident', s)
      continue
    }
    if (isDigit(c)) {
      let s = ''
      let bad = false
      const take = () => { s += adv() }
      // digit run with underscores only between two digits of the run
      const run = (ok) => {
        let any = false
        while (i < n) {
          if (ok(cs[i])) { take(); any = true }
          else if (cs[i] === '_' && any && ok(cs[i - 1]) && ok(cs[i + 1])) take()
          else break
        }
        return any
      }
      const p = (cs[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        take(); take()
        const ok = p === 'x' ? isHex : p === 'b' ? isBin : isOct
        if (!run(ok)) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { take(); run(isDigit) }
        const e = cs[i]
        if (e === 'e' || e === 'E') {
          if (isDigit(cs[i + 1])) { take(); run(isDigit) }
          else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { take(); take(); run(isDigit) }
        }
      }
      if (i < n && isIdPart(cs[i])) bad = true
      if (bad) {
        while (i < n && isIdPart(cs[i])) take()
        throw new ScanError(sl, sc, `invalid number ${s}`)
      }
      push('number', s)
      continue
    }
    if (c === '"') {
      adv()
      let s = ''
      while (true) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const el = line, ec = col
        const d = cs[i]
        if (d === '\n') throw new ScanError(el, ec, 'newline in string')
        adv()
        if (d === '"') break
        if (d !== '\\') { s += d; continue }
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = adv()
        const bad = () => new ScanError(el, ec, `invalid escape \\${e}`)
        if (e === 'n') s += '\n'
        else if (e === 't') s += '\t'
        else if (e === 'r') s += '\r'
        else if (e === '\\') s += '\\'
        else if (e === '"') s += '"'
        else if (e === '0') s += '\0'
        else if (e === 'x') {
          if (!(isHex(cs[i]) && isHex(cs[i + 1]))) throw bad()
          s += String.fromCodePoint(parseInt(cs[i] + cs[i + 1], 16))
          advN(2)
        } else if (e === 'u') {
          if (cs[i] !== '{') throw bad()
          let j = i + 1
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (!h || cs[j] !== '}') throw bad()
          const v = parseInt(h, 16)
          if (v > 0x10ffff) throw bad()
          s += String.fromCodePoint(v)
          advN(j + 1 - i)
        } else throw bad()
      }
      push('string', s)
      continue
    }
    const two = c + (cs[i + 1] || '')
    if (PUNCT2.includes(two)) { advN(2); push('punct', two); continue }
    if (PUNCT1.includes(c)) { adv(); push('punct', c); continue }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}
