import { readFileSync } from 'node:fs'
import { scan, ScanError } from './scan.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
const text = readFileSync(0).toString('utf8')
try {
  const toks = scan(text)
  let out = ''
  if (mode === 'tokens') {
    for (const t of toks) {
      const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.body) : t.body
      out += `${t.line}:${t.col} ${t.kind} ${body}\n`
    }
  } else {
    for (const k of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      out += `${k} ${toks.filter((t) => t.kind === k).length}\n`
    }
    out += `total ${toks.length}\n`
  }
  process.stdout.write(out)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
