  if (mode === 'tokens') {
    for (const t of toks) {
      const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.body) : t.body
      out += `${t.line}:${t.col} ${t.kind} ${body}\n`
    }
  } else {
    for (const k of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      out += `${k} ${toks.filter((t) => t.kind === k).length}\n`
    }
    out += `total ${toks.length}\n`
  }
  process.stdout.write(out)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
