/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'

class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

const newTable = () => ({ t: 'table', m: new Map(), explicit: false })
const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const isEnd = (c) => c === undefined || c === '#' || c === ';'

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class LineParser {
  constructor(s) { this.s = s; this.i = 0 }
  peek() { return this.s[this.i] }
  ws() { while (isWs(this.s[this.i])) this.i++ }

  string() {
    const q = this.s[this.i++]
    let out = ''
    if (q === "'") {
      const j = this.s.indexOf("'", this.i)
      if (j < 0) fail('unterminated string')
      out = this.s.slice(this.i, j)
      this.i = j + 1
      return out
    }
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      const e = this.s[this.i]
      if (e === undefined) fail('unterminated string')
      const cp = String.fromCodePoint(e.codePointAt(0))
      this.i += cp.length
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, e)) out += map[e]
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail('invalid escape \\' + cp)
    }
  }

  name() {
    this.ws()
    const c = this.peek()
    if (c === '"' || c === "'") return this.string()
    const st = this.i
    while (isNameChar(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = [this.name()]
    for (;;) {
      this.ws()
      if (this.peek() !== '.') return names
      this.i++
      names.push(this.name())
    }
  }

  value(prefix) {
    this.ws()
    const c = this.peek()
    if (isEnd(c) || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.string() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    if (INT.test(w)) {
      let b = BigInt(w.replace(/_/g, ''))
      return { t: 'integer', v: b.toString() }
    }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }

  array(prefix) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      const c = this.peek()
      if (isEnd(c)) fail('unterminated array')
      if (c === ']') { this.i++; return { t: 'array', items, aot: false } }
      items.push(this.value(prefix + '[' + items.length + ']'))
      this.ws()
      const d = this.peek()
      if (d === ',') { this.i++; continue }
      if (d === ']') { this.i++; return { t: 'array', items, aot: false } }
      fail('unterminated array')
    }
  }

  inline(prefix) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.peek() === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      if (isEnd(this.peek())) fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value(prefix)
      assign(tbl, prefix, names, v)
      this.ws()
      const d = this.peek()
      if (d === ',') { this.i++; continue }
      if (d === '}') { this.i++; return tbl }
      fail('unterminated inline table')
    }
  }
}

const joinPath = (base, names) => [...base, ...names].join('.')

function descend(node) {
  return node.t === 'array' && node.aot ? node.items[node.items.length - 1] : node
}

// Walk (creating tables) `names` below `tbl`; returns the table reached.
function walk(tbl, base, names) {
  let cur = tbl
  for (let k = 0; k < names.length; k++) {
    let n = cur.m.get(names[k])
    if (n === undefined) { n = newTable(); cur.m.set(names[k], n) }
    else {
      n = descend(n)
      if (n.t !== 'table') fail(joinPath(base, names.slice(0, k + 1)) + ' is not a table')
    }
    cur = n
  }
  return cur
}

function assign(tbl, base, names, v) {
  const parent = walk(tbl, base, names.slice(0, -1))
  const last = names[names.length - 1]
  if (parent.m.has(last)) fail('key ' + joinPath(base, names) + ' is defined twice')
  parent.m.set(last, v)
}

function parse(text) {
  const root = newTable()
  let cur = root
  let curPath = []
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  lines.forEach((line, idx) => {
    try {
      const p = new LineParser(line)
      p.ws()
      if (isEnd(p.peek())) return
      if (p.peek() === '[') {
        p.i++
        const aot = p.peek() === '['
        if (aot) p.i++
        const names = p.dotted()
        p.ws()
        if (p.peek() !== ']') fail('unterminated table header')
        p.i++
        if (aot) {
          if (p.peek() !== ']') fail('unterminated table header')
          p.i++
        }
        p.ws()
        if (!isEnd(p.peek())) fail('trailing text after a table header')
        const parent = walk(root, [], names.slice(0, -1))
        const last = names[names.length - 1]
        const path = names.join('.')
        const ex = parent.m.get(last)
        if (aot) {
          const fresh = newTable()
          if (ex === undefined) parent.m.set(last, { t: 'array', items: [fresh], aot: true })
          else if (ex.t === 'array' && ex.aot) ex.items.push(fresh)
          else fail(path + ' is not an array of tables')
          cur = fresh
        } else {
          if (ex === undefined) {
            cur = newTable()
            parent.m.set(last, cur)
          } else if (ex.t !== 'table') fail(path + ' is not a table')
          else if (ex.explicit) fail('table ' + path + ' is defined twice')
          else cur = ex
          cur.explicit = true
        }
        curPath = names
        return
      }
      const names = p.dotted()
      p.ws()
      if (p.peek() !== '=') fail('expected key = value')
      p.i++
      const v = p.value(joinPath(curPath, names))
      p.ws()
      if (!isEnd(p.peek())) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}
