/** Parses election text into { candidates, ballots }; throws Error('error: ...') on the first fault. */
const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const n = i + 1
    const fail = (m) => new Error(`error: line ${n}: ${m}`)
    const [word, ...args] = line.split(/\s+/)
    if (word === 'candidates') {
      if (candidates !== null || ballots.length) throw fail('candidates must be declared once, before any ballot')
      if (args.length === 0) throw fail('expected candidates <name>...')
      const seen = new Set()
      for (const a of args) {
        if (!NAME.test(a)) throw fail(`invalid candidate name ${a}`)
        if (seen.has(a)) throw fail(`candidate ${a} is declared twice`)
        seen.add(a)
      }
      candidates = args
    } else if (word === 'ballot') {
      if (candidates === null) throw fail('candidates must be declared once, before any ballot')
      if (args.length < 2) throw fail('expected ballot <count> <candidate>...')
      if (!COUNT.test(args[0])) throw fail('count must be a positive integer')
      const names = args.slice(1)
      const seen = new Set()
      for (const a of names) {
        if (!candidates.includes(a)) throw fail(`unknown candidate ${a}`)
        if (seen.has(a)) throw fail(`candidate ${a} is repeated`)
        seen.add(a)
      }
      ballots.push({ count: BigInt(args[0]), names })
    } else {
      throw fail(`unknown directive ${word}`)
    }
  }
  if (candidates === null) throw new Error('error: no candidates')
  return { candidates, ballots }
}
EOF
