/** Runs the instant-runoff count. Returns { rounds, winner }. */
export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = [] // Map name -> votes per round
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const pick = b.names.find((x) => continuing.has(x))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    history.push(votes)
    const listing = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : 1))
    const round = { listing: listing.map(([n, v]) => [n, String(v)]), exhausted: String(total - active), eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [n, v] of votes) if (v * 2n > active) return { rounds, winner: n }
    let tied = [...votes]
    const min = tied.reduce((m, [, v]) => (v < m ? v : m), tied[0][1])
    tied = tied.filter(([, v]) => v === min).map(([n]) => n)
    for (let r = 0; r < history.length && tied.length > 1; r++) {
      const vs = tied.map((n) => history[r].get(n))
      const m = vs.reduce((a, b) => (b < a ? b : a))
      if (vs.some((v) => v !== m)) {
        tied = tied.filter((n) => history[r].get(n) === m)
        r = -1
      }
    }
    const out = tied.reduce((a, b) => (b > a ? b : a))
    continuing.delete(out)
    round.eliminated = out
  }
}
