  const changes = []
  let i = 0, j = 0, cur = null
  const close = () => { if (cur) { cur.be = i; cur.se = j; changes.push(cur); cur = null } }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) { close(); i++; j++; continue }
    if (!cur) cur = { bs: i, ss: j }
    if (j >= m || (i < n && L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
